#nullable enable // autogenerated

using System.Collections.Generic;
using System.Diagnostics.CodeAnalysis;
using MVZ2.GameContent.Detections;
using MVZ2.Vanilla.Detections;
using MVZ2.Vanilla.Projectiles;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Modifiers;
using UnityEngine;

namespace MVZ2.GameContent.Buffs.Projectiles
{
    [AutoBuffDefinition(VanillaBuffNames.Projectile.homingProjectile)]
    public class HomingProjectileBuff : BuffDefinition
    {
        public HomingProjectileBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new BooleanModifier(VanillaProjectileProps.IGNORE_SHIELDS, true));
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);
            var projectile = buff.GetEntity();
            if (projectile == null)
                return;
            var targetId = GetTarget(buff);
            var target = targetId?.GetEntity(buff.Level);
            if (projectile.IsTimeInterval(4))
            {
                if (!IsTargetValid(projectile, target))
                {
                    var newTarget = FindNextTarget(projectile);
                    target = newTarget;
                    if (target == null)
                    {
                        targetId = null;
                    }
                    else
                    {
                        targetId = new EntityID(target);
                    }
                    SetTarget(buff, targetId);
                }
            }
            if (IsTargetValid(projectile, target))
            {
                var speed = GetSpeed(buff);

                var velocity = projectile.Velocity;
                var targetPosition = GetTargetPosition(target);
                Vector3 targetDir = (targetPosition - projectile.GetCenter()).normalized;

                if (targetDir != Vector3.zero)
                {
                    Vector3 currentDir = velocity.normalized;
                    float maxRadiansDelta = GetTurnRate(buff) * Mathf.Deg2Rad;
                    Vector3 newDir = Vector3.RotateTowards(currentDir, targetDir, maxRadiansDelta, 0.0f);
                    projectile.Velocity = newDir * speed;
                }
            }
        }
        public static bool IsTargetValid(Entity projectile, [NotNullWhen(true)] Entity? target)
        {
            var mainCollider = target?.GetMainCollider();
            return target != null && (target.ExistsAndAlive() || target.AssumeAlive()) && (mainCollider != null && !projectile.IsProjectileColliderIgnored(mainCollider));
        }
        public static Entity? FindNextTarget(Entity projectile)
        {
            return detector.DetectEntityWithTheLeast(projectile, t => (t.GetCenter() - projectile.GetCenter()).sqrMagnitude);
        }
        public static void FindAllNextTargets(Entity projectile, List<Entity> results)
        {
            detector.DetectEntities(projectile, results);
        }
        public static Vector3 GetTargetPosition(Entity target)
        {
            var targetBounds = target.GetBounds();
            var targetPosition = targetBounds.center;
            var targetGroundY = target.Level.GetGroundY(targetPosition.x, targetPosition.z);
            targetPosition.y = (Mathf.Max(targetBounds.min.y, targetGroundY) + Mathf.Max(targetBounds.max.y, targetGroundY)) * 0.5f;
            return targetPosition;
        }
        public static float GetSpeed(Buff buff) => buff.GetProperty<float>(PROP_SPEED);
        public static void SetSpeed(Buff buff, float value) => buff.SetProperty(PROP_SPEED, value);
        public static float GetTurnRate(Buff buff) => buff.GetProperty<float>(PROP_TURN_RATE);
        public static void SetTurnRate(Buff buff, float value) => buff.SetProperty(PROP_TURN_RATE, value);
        public static EntityID? GetTarget(Buff buff) => buff.GetProperty<EntityID>(PROP_TARGET);
        public static void SetTarget(Buff buff, EntityID? value) => buff.SetProperty(PROP_TARGET, value);

        private static Detector detector = new LawnDetector()
        {
            canDetectInvisible = false,
            factionTarget = FactionTarget.Hostile
        };
        public static readonly VanillaBuffPropertyMeta<float> PROP_SPEED = new VanillaBuffPropertyMeta<float>("speed");
        public static readonly VanillaBuffPropertyMeta<float> PROP_TURN_RATE = new VanillaBuffPropertyMeta<float>("turn_rate", 30f);
        public static readonly VanillaBuffPropertyMeta<EntityID> PROP_TARGET = new VanillaBuffPropertyMeta<EntityID>("target");
    }
}
